v = 10
all_triples = list(combinations(range(v), 3))

def find_bibd_greedy():
    """Try to find BIBD(10,3,2) using greedy + backtracking"""
    pair_count = {}
    for i in range(v):
        for j in range(i+1, v):
            pair_count[(i,j)] = 0

    selected = []

    def backtrack(triple_idx, pair_count, selected):
        if len(selected) == 30:
            # Check all pairs covered exactly 2 times
            return all(c == 2 for c in pair_count.values())

        if triple_idx >= len(all_triples):
            return False

        # Pruning: check if remaining triples can cover remaining pairs
        remaining_blocks = 30 - len(selected)
        remaining_triples = len(all_triples) - triple_idx
        if remaining_triples < remaining_blocks:
            return False

        # Try including this triple
        triple = all_triples[triple_idx]
        pairs_in_triple = list(combinations(triple, 2))

        # Check if adding this triple would exceed lambda=2 for any pair
        can_add = all(pair_count[(min(p[0],p[1]), max(p[0],p[1]))] < 2 
                     for p in pairs_in_triple)

        if can_add:
            for p in pairs_in_triple:
                pair_count[(min(p[0],p[1]), max(p[0],p[1]))] += 1
            selected.append(triple)

            if backtrack(triple_idx + 1, pair_count, selected):
                return True

            selected.pop()
            for p in pairs_in_triple:
                pair_count[(min(p[0],p[1]), max(p[0],p[1]))] -= 1

        # Try skipping this triple
        return backtrack(triple_idx + 1, pair_count, selected)

    if backtrack(0, pair_count, selected):
        return selected
    return None

