import random

def random_bibd_search(v, k, lam, max_iter=50000):
    b_target = lam * v * (v-1) // (k * (k-1))
    all_triples = list(combinations(range(v), 3))
    all_triples_set = set(all_triples)

    def score(sel):
        pair_count = {}
        for i in range(v):
            for j in range(i+1, v):
                pair_count[(i,j)] = 0
        for block in sel:
            for p in combinations(block, 2):
                pair_count[(min(p), max(p))] += 1
        return sum((c - lam)**2 for c in pair_count.values())

    for attempt in range(20):
        random.seed(attempt * 17 + 3)

        selected = list(random.sample(all_triples, b_target))
        selected_set = set(selected)

        s = score(selected)

        for it in range(max_iter):
            if s == 0:
                return selected

