            old_triple = selected[idx]

            # Find a random triple not in selected
            candidates = [t for t in all_triples if t not in selected_set]
            if not candidates:
                break
            new_triple = random.choice(candidates)

            selected_set.discard(old_triple)
            selected[idx] = new_triple
            selected_set.add(new_triple)
            new_s = score(selected)

            if new_s <= s:
                s = new_s
            else:
                selected_set.discard(new_triple)
                selected[idx] = old_triple
                selected_set.add(old_triple)

        print(f"Attempt {attempt}: score = {s}")

    return None

